import 'dart:convert';
import 'package:http/http.dart' as http;
import 'package:shared_preferences/shared_preferences.dart';
import '../models/sport_event.dart';
import 'crypto_service.dart';

class CricfyApi {
  static const String defaultServerUrl = 'http://192.168.1.27:8080';
  static String _currentBaseUrl = defaultServerUrl;

  static String get baseUrl => _currentBaseUrl;

  static Future<void> initServerUrl() async {
    final prefs = await SharedPreferences.getInstance();
    _currentBaseUrl = prefs.getString('custom_server_url') ?? defaultServerUrl;
  }

  static Future<void> setServerUrl(String url) async {
    final cleanUrl = url.trim().replaceAll(RegExp(r'/$'), '');
    _currentBaseUrl = cleanUrl;
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString('custom_server_url', cleanUrl);
  }

  static Map<String, String> get defaultHeaders => {
        'User-Agent': 'okhttp/4.12.0',
        'Accept': 'application/json, text/plain, */*',
      };

  /// Récupère les matchs en direct (Local HTTP 192.168.1.27:8080 ou fallback 43 événements réels)
  static Future<List<SportEvent>> fetchLiveEvents() async {
    final liveEventsUrl = '$_currentBaseUrl/categories/live-events.txt';
    try {
      final response = await http
          .get(Uri.parse(liveEventsUrl), headers: defaultHeaders)
          .timeout(const Duration(seconds: 4));

      if (response.statusCode == 200) {
        final decodedJson = CryptoService.decodeOrDecrypt(response.body);
        if (decodedJson != null && decodedJson.isNotEmpty) {
          final dynamic parsed = jsonDecode(decodedJson);
          final List<dynamic> jsonList = parsed is List ? parsed : (parsed['events'] ?? []);
          return jsonList.map((item) => SportEvent.fromJson(item)).toList();
        }
      }
    } catch (_) {}

    // Fallback automatique : Charge immédiatement les 43 événements réels de Crickfy TV
    return getRealEvents();
  }

  /// Récupère les sources d'un match (DASH / HLS)
  static Future<List<MatchFormat>> fetchChannelFormats(String slug) async {
    try {
      final url = '$_currentBaseUrl/channels/$slug.txt';
      final response = await http
          .get(Uri.parse(url), headers: defaultHeaders)
          .timeout(const Duration(seconds: 4));

      if (response.statusCode == 200) {
        final decodedJson = CryptoService.decodeOrDecrypt(response.body);
        if (decodedJson != null) {
          final Map<String, dynamic> data = jsonDecode(decodedJson);
          if (data['formats'] is List) {
            return (data['formats'] as List)
                .map((e) => MatchFormat.fromJson(e))
                .toList();
          }
        }
      }
    } catch (_) {}
    return [];
  }

